code_sketch:
struct op { void (*done)(struct op *, int); int rc; };

static void *worker(void *arg) {
    struct op *o = arg;
    o->rc = do_work();            /* runs off the caller's thread */
    o->done(o, o->rc);            /* exactly-once completion */
    return NULL;
}

pthread_t t;
pthread_create(&t, NULL, worker, op);   /* start now; caller continues */
pthread_detach(t);                      /* reap the thread */

